int main(void) {
   int x, y, z;
   scanf(“%d %d”, &x, &y);
   if (x < 0) {
       if (y < 0) {
           z = x - y;
       } else {
           z = x + y;
       }
       z = 5 * z;
   } else {
       z = 2 * x * -y;
   }
   if (z >= 0) {
       printf(“%d is positive\n”, z);
   } else {
       printf(“%d is negative\n”, z);
   }
   return 1;
}

